import pandas as pd
from datetime import datetime

def task_func(excel_directory: str, file_name: str, column_name: str, start_date: str, end_date: str) -> pd.DataFrame:
    file_path = os.path.join(excel_directory, file_name)

    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The file {file_path} does not exist.")

    try:
        df = pd.read_excel(file_path)
    except Exception as e:
        raise ValueError(f"Error reading the Excel file: {e}")

    if column_name not in df.columns:
        raise ValueError(f"The column '{column_name}' does not exist in the DataFrame.")

    try:
        start_date_parsed = datetime.strptime(start_date, "%Y-%m-%d")
        end_date_parsed = datetime.strptime(end_date, "%Y-%m-%d")
    except ValueError:
        raise ValueError("start_date and end_date must be in 'YYYY-MM-DD' format.")

    if df[column_name].dtype == 'object':
        df[column_name] = pd.to_datetime(df[column_name], errors='coerce')

    if df[column_name].isna().all():
        raise ValueError(f"All values in column '{column_name}' are not valid dates.")

    mask = (df[column_name] >= start_date_parsed) & (df[column_name] <= end_date_parsed)
    filtered_df = df[mask]

    return filtered_df

import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        raise FileNotFoundError(f"Script not found: {script_path}")

    # Start the script in a subprocess
    process = subprocess.Popen([script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    # Get the process object for monitoring
    proc = psutil.Process(process.pid)

    cpu_usage = 0.0
    memory_usage = 0.0
    start_time = time.time()

    try:
        while True:
            # Check if process has finished
            if process.poll() is not None:
                break

            # Check if timeout has been reached
            if time.time() - start_time > timeout:
                # Terminate the process if it exceeds timeout
                proc.terminate()
                try:
                    proc.wait(timeout=2)
                except psutil.TimeoutExpired:
                    proc.kill()
                break

            # Get current CPU and memory usage
            try:
                cpu_percent = proc.cpu_percent(interval=0.1)
                memory_info = proc.memory_info()
                memory_rss = memory_info.rss

                # Accumulate CPU usage (in percentage over time)
                cpu_usage += cpu_percent * 0.1  # 0.1 seconds interval

                # Accumulate memory usage (RSS in bytes)
                memory_usage += memory_rss

            except (psutil.NoSuchProcess, psutil.AccessDenied):
                # Process might have terminated or been denied access
                break

            # Small delay to avoid high CPU usage in the loop
            time.sleep(0.05)

    except Exception:
        # Ensure process is terminated in case of unexpected errors
        if process.poll() is None:
            proc.terminate()
            try:
                proc.wait(timeout=2)
            except psutil.TimeoutExpired:
                proc.kill()

    # Final check for process state
    if process.poll() is None:
        proc.terminate()
        try:
            proc.wait(timeout=2)
        except psutil.TimeoutExpired:
            proc.kill()

    return {
        'CPU Usage': cpu_usage,
        'Memory Usage': memory_usage
    }

import xml.etree.ElementTree as ET
import csv

def task_func(xml_content, output_csv_path):
    try:
        # Parse the XML content
        root = ET.fromstring(xml_content)

        # Extract headers from the first element's attributes
        headers = []
        for child in root:
            for attr in child.attrib:
                if attr not in headers:
                    headers.append(attr)

        # Write to CSV
        with open(output_csv_path, 'w', newline='', encoding='utf-8') as csvfile:
            writer = csv.DictWriter(csvfile, fieldnames=headers)
            writer.writeheader()

            # Write each element as a row
            for child in root:
                row = {}
                for attr in child.attrib:
                    row[attr] = child.attrib[attr]
                writer.writerow(row)

    except ET.ParseError as e:
        raise ET.ParseError(f"Failed to parse XML content: {e}")
    except IOError as e:
        raise IOError(f"Failed to write to CSV file at {output_csv_path}: {e}")

