def task_func(directory: str, pattern: str = r"(?<!Distillr)\\AcroTray\.exe") -> dict:
    result = {}
    compiled_pattern = re.compile(pattern)

    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            if compiled_pattern.search(file_path):
                try:
                    with open(file_path, 'rb') as f:
                        file_hash = hashlib.sha256(f.read()).hexdigest()
                        result[file_path] = file_hash
                except (IOError, OSError):
                    continue

    return result

import shutil
import pathlib

def task_func(source_path, destination_path):
    source = pathlib.Path(source_path)
    destination = pathlib.Path(destination_path)

    if not source.exists():
        raise ValueError("source_path does not exist")
    if not source.is_dir():
        raise ValueError("source_path is not a directory")

    copied_files = []

    for item in source.iterdir():
        if item.is_file():
            shutil.copy2(item, destination)
            copied_files.append(item.name)

    return (source.name, copied_files)

