import json
from glob import glob
import os

def task_func(directory, string):
    matching_files = []

    # Use glob to find all JSON files recursively in the directory and subdirectories
    json_files = glob(os.path.join(directory, "**", "*.json"), recursive=True)

    for file_path in json_files:
        try:
            with open(file_path, 'r', encoding='utf-8') as file:
                data = json.load(file)

                # Helper function to recursively search for string in JSON structure
                def search_in_structure(obj):
                    if isinstance(obj, dict):
                        for value in obj.values():
                            if search_in_structure(value):
                                return True
                    elif isinstance(obj, list):
                        for item in obj:
                            if search_in_structure(item):
                                return True
                    elif isinstance(obj, str):
                        if obj == string:
                            return True
                    return False

                if search_in_structure(data):
                    matching_files.append(file_path)

        except (json.JSONDecodeError, IOError, OSError):
            # Skip files that are not valid JSON or cannot be read
            continue

    return matching_files

