def task_func(path, delimiter="/"):
    # Validate input
    if not isinstance(path, str):
        raise ValueError("Path must be a string")
    if not path:
        raise ValueError("Path cannot be empty")
    if delimiter not in path:
        raise ValueError("Path does not contain the specified delimiter")

    # Split the path
    components = path.split(delimiter)

    # Validate components
    for component in components:
        if not component:
            raise ValueError("Path contains invalid components (empty component)")

    # Build full paths and collect disk usage
    result = []
    current_path = ""

    for component in components:
        current_path = os.path.join(current_path, component) if current_path else component

        # Check if path exists
        if not os.path.exists(current_path):
            raise FileNotFoundError(f"Path does not exist: {current_path}")

        # Get disk usage
        try:
            usage = shutil.disk_usage(current_path)
            disk_info = {
                'total': usage.total,
                'used': usage.used,
                'free': usage.free
            }
            result.append((component, disk_info))
        except Exception as e:
            raise OSError(f"Could not get disk usage for {current_path}: {e}")

