def find_unique_element(nums):
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2

        # Check if mid is even or odd
        # If mid is even, it should be the start of a pair
        # If mid is odd, it should be the end of a pair
        if mid % 2 == 0:
            # Even index: should pair with next element
            if mid + 1 < len(nums) and nums[mid] == nums[mid + 1]:
                # The unique element is on the right side
                left = mid + 2
            else:
                # The unique element is on the left side (including mid)
                right = mid
        else:
            # Odd index: should pair with previous element
            if nums[mid] == nums[mid - 1]:
                # The unique element is on the right side
                left = mid + 1
            else:
                # The unique element is on the left side (including mid)
                right = mid - 1

    return nums[left]

def sum_amicable_numbers(n):
    def sum_of_divisors(num):
        divisors_sum = 1  # 1 is always a divisor (except for num = 1)
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                divisors_sum += i
                if i != num // i:  # Avoid counting the square root twice
                    divisors_sum += num // i
        return divisors_sum

    amicable_numbers = set()

    for i in range(2, n + 1):
        if i in amicable_numbers:
            continue

        sum_i = sum_of_divisors(i)
        if sum_i != i and sum_of_divisors(sum_i) == i and sum_i <= n:
            amicable_numbers.add(i)
            amicable_numbers.add(sum_i)

    return sum(amicable_numbers)

def is_magic_square(matrix):
    if not matrix or not matrix[0]:
        return False

    n = len(matrix)

    # Check if matrix is square
    for row in matrix:
        if len(row) != n:
            return False

    # Calculate the sum of the first row to use as reference
    target_sum = sum(matrix[0])

    # Check rows
    for row in matrix:
        if sum(row) != target_sum:
            return False

    # Check columns
    for col in range(n):
        col_sum = sum(matrix[row][col] for row in range(n))
        if col_sum != target_sum:
            return False

    # Check main diagonal
    main_diag_sum = sum(matrix[i][i] for i in range(n))
    if main_diag_sum != target_sum:
        return False

    # Check anti-diagonal
    anti_diag_sum = sum(matrix[i][n-1-i] for i in range(n))
    if anti_diag_sum != target_sum:
        return False

    return True

