def max_bitonic_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Initialize arrays to store maximum increasing and decreasing sums
    # ending at each index
    inc_sum = [0] * n
    dec_sum = [0] * n

    # Fill inc_sum: maximum sum of increasing subsequence ending at i
    for i in range(n):
        inc_sum[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc_sum[i] = max(inc_sum[i], inc_sum[j] + arr[i])

    # Fill dec_sum: maximum sum of decreasing subsequence starting at i
    for i in range(n - 1, -1, -1):
        dec_sum[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec_sum[i] = max(dec_sum[i], dec_sum[j] + arr[i])

    # Find maximum bitonic sum
    max_sum = 0
    for i in range(n):
        # Bitonic sequence with peak at i
        # Sum = increasing part ending at i + decreasing part starting at i - arr[i]
        # (subtract arr[i] once because it's counted twice)
        bitonic_sum = inc_sum[i] + dec_sum[i] - arr[i]
        max_sum = max(max_sum, bitonic_sum)

    return max_sum

def babylonian_sqrt(n, tolerance=1e-10):
    if n < 0:
        raise ValueError("Cannot compute square root of negative number")
    if n == 0 or n == 1:
        return n

    # Initial guess
    x = n / 2.0

    while True:
        # Improved guess using the Babylonian formula
        root = 0.5 * (x + n / x)

        # Check for convergence
        if abs(root - x) < tolerance:
            return root

        x = root

