    # Count positions where bits differ
    diff_positions = []
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            diff_positions.append(i)

    # If odd number of differences, impossible to convert with swaps
    if len(diff_positions) % 2 == 1:
        return -1

    # Count swaps needed
    # Each swap fixes two positions
    return len(diff_positions) // 2

