def count_rotations(arr):
    n = len(arr)
    if n == 0:
        return 0

    left, right = 0, n - 1

    while left <= right:
        # If the array is already sorted
        if arr[left] <= arr[right]:
            return left

        mid = (left + right) // 2

        # Check if mid is the pivot (smallest element)
        # Pivot is the only element where previous element is greater than current
        if mid > 0 and arr[mid] < arr[mid - 1]:
            return mid

        # If left half is sorted, pivot must be in right half
        if arr[left] <= arr[mid]:
            left = mid + 1
        else:
            # Left half is not sorted, so pivot is in left half
            right = mid - 1

    return 0

def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0 or n == 1:
        return True

    # Find the square root using binary search
    left, right = 1, n // 2

    while left <= right:
        mid = (left + right) // 2
        square = mid * mid

        if square == n:
            return True
        elif square < n:
            left = mid + 1
        else:
            right = mid - 1

    return False

