        with open(file_path1, 'r') as f1:
            if not f1.read():
                raise ValueError("File 1 is empty")
        with open(file_path2, 'r') as f2:
            if not f2.read():
                raise ValueError("File 2 is empty")

        # Read files content
        with open(file_path1, 'r') as f1:
            content1 = f1.readlines()
        with open(file_path2, 'r') as f2:
            content2 = f2.readlines()

    except FileNotFoundError as e:
        raise FileNotFoundError(f"File not found: {e}")
    except Exception as e:
        raise Exception(f"IO error: {e}")

    # Use difflib to compare files
    diff = list(ndiff(content1, content2))

    # Process differences into DataFrame
    rows = []
    for i, line in enumerate(diff):
        if line.startswith(' '):
            # No change
            rows.append({
                'Line Number': i + 1,
                'Status': ' ',
                'Content': line[2:].rstrip('\n')
            })
        elif line.startswith('-'):
            # Line present in first file but not in second
            rows.append({
                'Line Number': i + 1,
                'Status': '-',
                'Content': line[2:].rstrip('\n')
            })
        elif line.startswith('+'):
            # Line present in second file but not in first
            rows.append({
                'Line Number': i + 1,
                'Status': '+',
                'Content': line[2:].rstrip('\n')
            })

    return pd.DataFrame(rows)

