from pathlib import Path

def task_func(dir_path: str, predicates: list) -> dict:
    # Check if directory exists and is actually a directory
    if not os.path.exists(dir_path) or not os.path.isdir(dir_path):
        raise FileNotFoundError("The specified directory does not exist or is not a directory")

    # Check if predicates are provided
    if not predicates:
        raise ValueError("No valid predicates are provided")

    # Remove duplicate predicates while preserving order
    unique_predicates = []
    seen = set()
    for predicate in predicates:
        if predicate not in seen:
            unique_predicates.append(predicate)
            seen.add(predicate)

    # Get all items in the directory
    try:
        items = os.listdir(dir_path)
    except OSError:
        raise FileNotFoundError("Unable to access the directory")

    # Evaluate each item against all predicates
    result = {}
    for item in items:
        item_results = []
        for predicate in unique_predicates:
            # Apply predicate to item name
            if callable(predicate):
                # If predicate is a callable (function), call it with item name
                try:
                    result_value = predicate(item)
                except Exception:
                    result_value = False
            elif isinstance(predicate, str):
                # If predicate is a string, treat it as a regex pattern
                try:
                    if re.search(predicate, item):
                        result_value = True
                    else:
                        result_value = False
                except re.error:
                    # If regex compilation fails, treat as exact match
                    result_value = (item == predicate)
            else:
                # For other types, convert to string and compare
                result_value = (str(predicate) == item)

            item_results.append(result_value)

        result[item] = item_results

    return result

