import os
import time
import glob
def task_func(r_script_path: str, output_path: str, duration: int) -> (bool, str):
    # Get the directory and base name of the output path
    output_dir = os.path.dirname(output_path)
    output_base = os.path.basename(output_path)

    # Get the list of files before running the R script
    if output_dir:
        initial_files = set(os.listdir(output_dir))
    else:
        initial_files = set(os.listdir('.'))

    # Execute the R script
    try:
        subprocess.run(['Rscript', r_script_path], check=True, capture_output=True)
    except subprocess.CalledProcessError:
        return False, 'File not generated within the specified duration.'

    # Check for the output file within the specified duration
    start_time = time.time()
    while time.time() - start_time < duration:
        # Check if the output file exists
        if output_dir:
            if os.path.exists(output_path):
                return True, 'File generated successfully within the specified duration.'
            # Check if any new files were created in the directory
            current_files = set(os.listdir(output_dir))
            if len(current_files) > len(initial_files):
                # Check if any of the new files matches the pattern
                new_files = current_files - initial_files
                for new_file in new_files:
                    if new_file.startswith(output_base.split('.')[0]) and new_file.endswith(output_base.split('.')[-1]):
                        return True, 'File generated successfully within the specified duration.'
        else:
            # Check current directory
            if os.path.exists(output_path):
                return True, 'File generated successfully within the specified duration.'
            # Check for new files
            current_files = set(os.listdir('.'))
            if len(current_files) > len(initial_files):
                new_files = current_files - initial_files
                for new_file in new_files:
                    if new_file.startswith(output_base.split('.')[0]) and new_file.endswith(output_base.split('.')[-1]):
                        return True, 'File generated successfully within the specified duration.'

        # Wait a bit before checking again
        time.sleep(0.1)

    # If we reach here, the file was not generated within the specified duration
    return False, 'File not generated within the specified duration.'

