import numpy as np
from scipy import stats
# Constants
FEATURES = ['feature1', 'feature2', 'feature3', 'feature4', 'feature5']
def task_func(df, dct):
    try:
        # Check if DataFrame is valid
        if df is None or not isinstance(df, dict):
            return "Invalid input"

        # Check if all required features exist
        for feature in FEATURES:
            if feature not in df:
                return "Invalid input"

        # Replace values based on mapping dictionary
        df_copy = {}
        for feature in FEATURES:
            df_copy[feature] = df[feature].copy()
            if feature in dct:
                df_copy[feature] = df_copy[feature].replace(dct[feature])

        # Calculate statistics for each feature
        result = {}
        for feature in FEATURES:
            data = df_copy[feature]

            # Convert to numeric, handling non-numeric values
            try:
                data_numeric = pd.to_numeric(data, errors='coerce').dropna()
            except:
                return "Invalid input"

            if len(data_numeric) == 0:
                return "Invalid input"

            # Calculate mean
            mean_val = np.mean(data_numeric)

            # Calculate median
            median_val = np.median(data_numeric)

            # Calculate mode
            try:
                mode_val = stats.mode(data_numeric, keepdims=True)[0][0]
            except:
                mode_val = data_numeric.iloc[0]  # Fallback to first value

            # Calculate variance
            variance_val = np.var(data_numeric)

            result[feature] = {
                'mean': mean_val,
                'median': median_val,
                'mode': mode_val,
                'variance': variance_val
            }

        return result

    except Exception as e:
        return "Invalid input"

