from scipy.spatial import distance
def task_func(points):
    if len(points) <= 1:
        return []

    distances = []
    for i in range(len(points) - 1):
        point1 = points[i]
        point2 = points[i + 1]

        # Handle tuples with single number
        if isinstance(point1, int) or isinstance(point1, float):
            point1 = (point1, point1)
        elif len(point1) == 1:
            point1 = (point1[0], point1[0])

        if isinstance(point2, int) or isinstance(point2, float):
            point2 = (point2, point2)
        elif len(point2) == 1:
            point2 = (point2[0], point2[0])

        # Calculate Euclidean distance
        dist = distance.euclidean(point1, point2)
        distances.append(dist)

    return distances

