from itertools import combinations
import math

def task_func(seq, letter_weight_dict):
    if not seq:
        return ""

    max_weight = -math.inf
    best_subsequence = ""

    # Try all possible subsequences
    for i in range(1, len(seq) + 1):
        for combo in combinations(range(len(seq)), i):
            subsequence = ''.join(seq[j] for j in combo)
            weight = sum(letter_weight_dict[char] for char in subsequence)

            if weight > max_weight:
                max_weight = weight
                best_subsequence = subsequence

    return best_subsequence

