import hashlib
import base64
import binascii
from django.http import HttpResponseBadRequest, HttpResponse
def task_func(data):
    try:
        # Check if required keys are present
        if 'username' not in data or 'password' not in data:
            raise KeyError("Missing required keys")

        username = data['username']
        password = data['password']

        # Decode the base64 password
        decoded_password = base64.b64decode(password)

        # Hash the provided password for comparison
        provided_hash = hashlib.sha256(decoded_password).digest()

        # Check if username is 'admin' and password hash matches 'password'
        expected_hash = hashlib.sha256(b'password').digest()

        if username == 'admin' and provided_hash == expected_hash:
            return HttpResponse('Login successful.', status=400)
        else:
            return HttpResponse('Login failed.', status=401)

    except (KeyError, UnicodeDecodeError, binascii.Error, ValueError):
        return HttpResponseBadRequest('Bad Request.')

import collections
import json
import os

def task_func(directory_path: str) -> dict:
    key_counts = collections.defaultdict(int)

    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            with open(file_path, 'r') as file:
                data = json.load(file)
                if isinstance(data, dict):
                    for key in data.keys():
                        key_counts[key] += 1
                elif isinstance(data, list):
                    for item in data:
                        if isinstance(item, dict):
                            for key in item.keys():
                                key_counts[key] += 1

    return dict(key_counts)

