import chardet
# Constants
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content

    if not content:
        return {}

    if from_encoding:
        encoding = from_encoding
    else:
        detected = chardet.detect(content)
        encoding = detected['encoding']

        if not encoding:
            raise ValueError("Unable to detect encoding for non-empty content")

    try:
        decoded_content = content.decode(encoding)
        reencoded_content = decoded_content.encode(to_encoding)
        json_data = json.loads(reencoded_content.decode(to_encoding))
        return json_data
    except Exception:
        # If any encoding/decoding fails, return empty dict
        return {}

import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd

def task_func(json_data: str, key_path: list):
    # Parse the JSON data
    try:
        data = json.loads(json_data)
    except json.JSONDecodeError:
        raise ValueError("Data string is empty or corrupted")

    # Navigate through the key path to extract the data
    current_data = data
    for key in key_path:
        if isinstance(current_data, dict) and key in current_data:
            current_data = current_data[key]
        elif isinstance(current_data, list) and isinstance(key, int) and 0 <= key < len(current_data):
            current_data = current_data[key]
        else:
            raise KeyError(f"Key '{key}' not found")

    # Extract numeric values
    numeric_values = []

    def extract_numbers(obj):
        if isinstance(obj, (int, float)) and not isinstance(obj, bool):
            numeric_values.append(obj)
        elif isinstance(obj, dict):
            for value in obj.values():
                extract_numbers(value)
        elif isinstance(obj, list):
            for item in obj:
                extract_numbers(item)

    extract_numbers(current_data)

    # Check if any numeric values were found
    if not numeric_values:
        raise ValueError("No numeric data found")

    # Create the boxplot
    fig, ax = plt.subplots(figsize=(8, 6))
    ax.boxplot(numeric_values)
    ax.set_title("Boxplot of Numeric Data")
    ax.set_ylabel("Values")

    return fig

import json
from datetime import datetime
from decimal import Decimal

def task_func(my_obj):
    def custom_serializer(obj):
        if isinstance(obj, datetime):
            return obj.isoformat()
        elif isinstance(obj, Decimal):
            return float(obj)
        elif hasattr(obj, '__dict__'):
            return obj.__dict__
        else:
            raise TypeError(f"Object of type {type(obj)} is not JSON serializable")

    return json.dumps(my_obj, default=custom_serializer)

import pandas as pd
from statistics import mean

def task_func(df: pd.DataFrame) -> dict:
    if 'Name' not in df.columns or 'Score' not in df.columns:
        raise ValueError("DataFrame must have 'Name' and 'Score' columns")

    # Group by Name and calculate average score
    grouped = df.groupby('Name')['Score'].apply(list)

    # Create dictionary of generators
    result = {}
    for name, scores in grouped.items():
        avg_score = mean(scores)
        # Create a generator that yields the tuple once
        result[name] = (lambda n, avg: (lambda: (n, avg))())(name, avg_score)

    # Convert to actual generators
    return {name: iter([(name, avg_score)]) for name, avg_score in 
            ((name, mean(scores)) for name, scores in grouped.items())}

import pandas as pd
import random
import re

def task_func(data_list, seed=None):
    if seed is not None:
        random.seed(seed)

    def apply_random_operation(s):
        substrings = [sub.strip() for sub in s.split(',') if sub.strip()]
        if len(substrings) <= 1:
            return s

        operation = random.choice(['remove', 'replace', 'shuffle', 'randomize'])

        if operation == 'remove':
            if len(substrings) > 1:
                index_to_remove = random.randint(0, len(substrings) - 1)
                substrings.pop(index_to_remove)
        elif operation == 'replace':
            index_to_replace = random.randint(0, len(substrings) - 1)
            substrings[index_to_replace] = 'random_string'
        elif operation == 'shuffle':
            random.shuffle(substrings)
        elif operation == 'randomize':
            # Create a random permutation of indices
            indices = list(range(len(substrings)))
            random.shuffle(indices)
            substrings = [substrings[i] for i in indices]

        return ', '.join(substrings)

    modified_strings = [apply_random_operation(s) for s in data_list]

    df = pd.DataFrame({
        'Original String': data_list,
        'Modified String': modified_strings
    })

    return df
